/// <summary>Pointer information (<c>CUpointer_attribute</c>)</summary>
public enum CUpointer_attribute : int
{
    /// <summary>The ::CUcontext on which a pointer was allocated or registered</summary>
    CU_POINTER_ATTRIBUTE_CONTEXT = 1,
    /// <summary>The ::CUmemorytype describing the physical location of a pointer</summary>
    CU_POINTER_ATTRIBUTE_MEMORY_TYPE = 2,
    /// <summary>The address at which a pointer&apos;s memory may be accessed on the device</summary>
    CU_POINTER_ATTRIBUTE_DEVICE_POINTER = 3,
    /// <summary>The address at which a pointer&apos;s memory may be accessed on the host</summary>
    CU_POINTER_ATTRIBUTE_HOST_POINTER = 4,
    /// <summary>A pair of tokens for use with the nv-p2p.h Linux kernel interface</summary>
    CU_POINTER_ATTRIBUTE_P2P_TOKENS = 5,
    /// <summary>Synchronize every synchronous memory operation initiated on this region</summary>
    CU_POINTER_ATTRIBUTE_SYNC_MEMOPS = 6,
    /// <summary>A process-wide unique ID for an allocated memory region</summary>
    CU_POINTER_ATTRIBUTE_BUFFER_ID = 7,
    /// <summary>Indicates if the pointer points to managed memory</summary>
    CU_POINTER_ATTRIBUTE_IS_MANAGED = 8,
    /// <summary>A device ordinal of a device on which a pointer was allocated or registered</summary>
    CU_POINTER_ATTRIBUTE_DEVICE_ORDINAL = 9,
    /// <summary>1 if this pointer maps to an allocation that is suitable for ::cudaIpcGetMemHandle, 0 otherwise *</summary>
    CU_POINTER_ATTRIBUTE_IS_LEGACY_CUDA_IPC_CAPABLE = 10,
    /// <summary>Starting address for this requested pointer</summary>
    CU_POINTER_ATTRIBUTE_RANGE_START_ADDR = 11,
    /// <summary>Size of the address range for this requested pointer</summary>
    CU_POINTER_ATTRIBUTE_RANGE_SIZE = 12,
    /// <summary>1 if this pointer is in a valid address range that is mapped to a backing allocation, 0 otherwise *</summary>
    CU_POINTER_ATTRIBUTE_MAPPED = 13,
    /// <summary>Bitmask of allowed ::CUmemAllocationHandleType for this allocation *</summary>
    CU_POINTER_ATTRIBUTE_ALLOWED_HANDLE_TYPES = 14,
    /// <summary>1 if the memory this pointer is referencing can be used with the GPUDirect RDMA API *</summary>
    CU_POINTER_ATTRIBUTE_IS_GPU_DIRECT_RDMA_CAPABLE = 15,
    /// <summary>Returns the access flags the device associated with the current context has on the corresponding memory referenced by the pointer given</summary>
    CU_POINTER_ATTRIBUTE_ACCESS_FLAGS = 16,
    /// <summary>Returns the mempool handle for the allocation if it was allocated from a mempool. Otherwise returns NULL. *</summary>
    CU_POINTER_ATTRIBUTE_MEMPOOL_HANDLE = 17,
    /// <summary>Size of the actual underlying mapping that the pointer belongs to *</summary>
    CU_POINTER_ATTRIBUTE_MAPPING_SIZE = 18,
    /// <summary>The start address of the mapping that the pointer belongs to *</summary>
    CU_POINTER_ATTRIBUTE_MAPPING_BASE_ADDR = 19,
    /// <summary>A process-wide unique id corresponding to the physical allocation the pointer belongs to *</summary>
    CU_POINTER_ATTRIBUTE_MEMORY_BLOCK_ID = 20,
    /// <summary>Returns in *data a boolean that indicates whether the pointer points to memory that is capable to be used for hardware accelerated decompression.</summary>
    CU_POINTER_ATTRIBUTE_IS_HW_DECOMPRESS_CAPABLE = 21,
    /// <summary>Returns in *data an integer representing the locality domain ordinal of the memory allocation, or -1 if the allocation is not localized to a locality domain.</summary>
    CU_POINTER_ATTRIBUTE_LOCALITY_DOMAIN_ORDINAL = 22,
}

/// <summary>Function properties (<c>CUfunction_attribute</c>)</summary>
public enum CUfunction_attribute : int
{
    /// <summary>The maximum number of threads per block, beyond which a launch of the function would fail. This number depends on both the function and the device on which the function is currently loaded.</summary>
