/// <summary>Error codes (<c>CUresult</c>)</summary>
public enum CUresult : int
{
    /// <summary>The API call returned with no errors. In the case of query calls, this also means that the operation being queried is complete (see ::cuEventQuery() and ::cuStreamQuery()).</summary>
    CUDA_SUCCESS = 0,
    /// <summary>This indicates that one or more of the parameters passed to the API call is not within an acceptable range of values.</summary>
    CUDA_ERROR_INVALID_VALUE = 1,
    /// <summary>The API call failed because it was unable to allocate enough memory or other resources to perform the requested operation.</summary>
    CUDA_ERROR_OUT_OF_MEMORY = 2,
    /// <summary>This indicates that the CUDA driver has not been initialized with ::cuInit() or that initialization has failed.</summary>
    CUDA_ERROR_NOT_INITIALIZED = 3,
    /// <summary>This indicates that the CUDA driver is in the process of shutting down.</summary>
    CUDA_ERROR_DEINITIALIZED = 4,
    /// <summary>This indicates profiler is not initialized for this run. This can happen when the application is running with external profiling tools like visual profiler.</summary>
    CUDA_ERROR_PROFILER_DISABLED = 5,
    CUDA_ERROR_PROFILER_NOT_INITIALIZED = 6,
    CUDA_ERROR_PROFILER_ALREADY_STARTED = 7,
    CUDA_ERROR_PROFILER_ALREADY_STOPPED = 8,
    /// <summary>This indicates that the CUDA driver that the application has loaded is a stub library. Applications that run with the stub rather than a real driver loaded will result in CUDA API returning this error.</summary>
    CUDA_ERROR_STUB_LIBRARY = 34,
    /// <summary>This indicates that the API call requires a newer CUDA driver than the one currently installed. Users should install an updated NVIDIA CUDA driver to allow the API call to succeed.</summary>
    CUDA_ERROR_CALL_REQUIRES_NEWER_DRIVER = 36,
    /// <summary>This indicates that requested CUDA device is unavailable at the current time. Devices are often unavailable due to use of ::CU_COMPUTEMODE_EXCLUSIVE_PROCESS or ::CU_COMPUTEMODE_PROHIBITED.</summary>
    CUDA_ERROR_DEVICE_UNAVAILABLE = 46,
    /// <summary>The API call failed because of a hardware resource required to bind memory to a multicast object is unavailable.</summary>
    CUDA_ERROR_MULTICAST_RESOURCE_FULL = 47,
    /// <summary>This indicates that no CUDA-capable devices were detected by the installed CUDA driver.</summary>
    CUDA_ERROR_NO_DEVICE = 100,
    /// <summary>This indicates that the device ordinal supplied by the user does not correspond to a valid CUDA device or that the action requested is invalid for the specified device.</summary>
    CUDA_ERROR_INVALID_DEVICE = 101,
