    CUDA_ERROR_DEVICE_NOT_LICENSED = 102,
    /// <summary>This indicates that the device kernel image is invalid. This can also indicate an invalid CUDA module.</summary>
    CUDA_ERROR_INVALID_IMAGE = 200,
    /// <summary>This most frequently indicates that there is no context bound to the current thread. This can also be returned if the context passed to an API call is not a valid handle (such as a context that has had ::cuCtxDestroy() invoked on it). This can also be returned if a user mixes different API versions (i.e. 3010 context with 3020 API calls). See ::cuCtxGetApiVersion() for more details. This can also be returned if the green context passed to an API call was not converted to a ::CUcontext using ::cuCtxFromGreenCtx API.</summary>
    CUDA_ERROR_INVALID_CONTEXT = 201,
    /// <summary>This indicated that the context being supplied as a parameter to the API call was already the active context.</summary>
    CUDA_ERROR_CONTEXT_ALREADY_CURRENT = 202,
    /// <summary>This indicates that a map or register operation has failed.</summary>
    CUDA_ERROR_MAP_FAILED = 205,
    /// <summary>This indicates that an unmap or unregister operation has failed.</summary>
    CUDA_ERROR_UNMAP_FAILED = 206,
    /// <summary>This indicates that the specified array is currently mapped and thus cannot be destroyed.</summary>
    CUDA_ERROR_ARRAY_IS_MAPPED = 207,
    /// <summary>This indicates that the resource is already mapped.</summary>
    CUDA_ERROR_ALREADY_MAPPED = 208,
    /// <summary>This indicates that there is no kernel image available that is suitable for the device. This can occur when a user specifies code generation options for a particular CUDA source file that do not include the corresponding device configuration.</summary>
    CUDA_ERROR_NO_BINARY_FOR_GPU = 209,
    /// <summary>This indicates that a resource has already been acquired.</summary>
    CUDA_ERROR_ALREADY_ACQUIRED = 210,
    /// <summary>This indicates that a resource is not mapped.</summary>
    CUDA_ERROR_NOT_MAPPED = 211,
    /// <summary>This indicates that a mapped resource is not available for access as an array.</summary>
    CUDA_ERROR_NOT_MAPPED_AS_ARRAY = 212,
    /// <summary>This indicates that a mapped resource is not available for access as a pointer.</summary>
