    /// <summary>This indicates that an uncorrectable ECC error was detected during execution.</summary>
    CUDA_ERROR_ECC_UNCORRECTABLE = 214,
    /// <summary>This indicates that the ::CUlimit passed to the API call is not supported by the active device.</summary>
    CUDA_ERROR_UNSUPPORTED_LIMIT = 215,
    /// <summary>This indicates that the ::CUcontext passed to the API call can only be bound to a single CPU thread at a time but is already bound to a CPU thread.</summary>
    CUDA_ERROR_CONTEXT_ALREADY_IN_USE = 216,
    /// <summary>This indicates that peer access is not supported across the given devices.</summary>
    CUDA_ERROR_PEER_ACCESS_UNSUPPORTED = 217,
    /// <summary>This indicates that a PTX JIT compilation failed.</summary>
    CUDA_ERROR_INVALID_PTX = 218,
    /// <summary>This indicates an error with OpenGL or DirectX context.</summary>
    CUDA_ERROR_INVALID_GRAPHICS_CONTEXT = 219,
    /// <summary>This indicates that an uncorrectable NVLink error was detected during the execution.</summary>
    CUDA_ERROR_NVLINK_UNCORRECTABLE = 220,
    /// <summary>This indicates that the PTX JIT compiler library was not found.</summary>
    CUDA_ERROR_JIT_COMPILER_NOT_FOUND = 221,
    /// <summary>This indicates that the provided PTX was compiled with an unsupported toolchain.</summary>
    CUDA_ERROR_UNSUPPORTED_PTX_VERSION = 222,
    /// <summary>This indicates that the PTX JIT compilation was disabled.</summary>
    CUDA_ERROR_JIT_COMPILATION_DISABLED = 223,
    /// <summary>This indicates that the ::CUexecAffinityType passed to the API call is not supported by the active device.</summary>
    CUDA_ERROR_UNSUPPORTED_EXEC_AFFINITY = 224,
