    /// <summary>This error indicates one or more resources are insufficient or non-applicable for the operation.</summary>
    CUDA_ERROR_INVALID_RESOURCE_CONFIGURATION = 915,
    /// <summary>This error indicates that an error happened during the key rotation sequence.</summary>
    CUDA_ERROR_KEY_ROTATION = 916,
    /// <summary>This error indicates that the requested operation is not permitted because the stream is in a detached state. This can occur if the green context associated with the stream has been destroyed, limiting the stream&apos;s operational capabilities.</summary>
